mapper.select:
select count(1)
from ry_rental.ry_rental_finance_ledger
where tenant_id = #{tenantId}
  and member_id = #{memberId}
  and ledger_no = #{ledgerNo}
  and is_delete = 0
for update

select coalesce(sum(case when direction = #{incomeCode} then amount
                         when direction = #{expenseCode} then -amount
                         when direction = #{unfreezeCode} then amount
                         when direction = #{reverseCode} then -amount
                         else 0 end), 0)
from ry_rental.ry_rental_finance_ledger
where tenant_id = #{tenantId} and member_id = #{memberId}
  and account_type = #{accountType}
  and ledger_status = #{successStatus} and is_delete = 0
